enum Phase { case draft; case published(version: Int) }

struct Post {
    var phase: Phase = .draft

    mutating func publish() {
        switch phase {
        case .draft: phase = .published(version: 1)
        case .published(let v): phase = .published(version: v + 1)
        }   // exhaustive: no default arm needed
    }
}

